<script lang="ts">const vector="<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"512\" height=\"512\" viewBox=\"0 0 512 512\" role=\"img\" aria-labelledby=\"title desc\"><title id=\"title\">Axon \u2014 disponible</title><desc id=\"desc\">Axon, petit axolotl orange de face. Yeux sym\u00e9triques, bouche centr\u00e9e, grande t\u00eate et petit corps.</desc><defs>\n<linearGradient id=\"skin\" x1=\"25%\" y1=\"0%\" x2=\"75%\" y2=\"100%\"><stop stop-color=\"#FFDB83\"/><stop offset=\".38\" stop-color=\"#FFBF2B\"/><stop offset=\".76\" stop-color=\"#FFAF00\"/><stop offset=\"1\" stop-color=\"#ED9900\"/></linearGradient>\n<linearGradient id=\"body-fill\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop stop-color=\"#E99A00\"/><stop offset=\"1\" stop-color=\"#FFBC29\"/></linearGradient>\n<linearGradient id=\"gill-fill\" x1=\"0%\" y1=\"0%\" x2=\"75%\" y2=\"100%\"><stop stop-color=\"#FFC046\"/><stop offset=\"1\" stop-color=\"#EA8D13\"/></linearGradient>\n<radialGradient id=\"gleam\" cx=\"35%\" cy=\"12%\" r=\"72%\"><stop stop-color=\"#FFF4D6\" stop-opacity=\".35\"/><stop offset=\".75\" stop-color=\"#FFF4D6\" stop-opacity=\"0\"/></radialGradient>\n</defs><style>\n.breathe {transform-origin:256px 350px;animation:breathe 4s ease-in-out infinite}\n.blink {transform-box:fill-box;transform-origin:center;animation:blink 5s linear infinite}\n.thinking .head-group {transform-origin:256px 282px;animation:ponder 4s ease-in-out infinite}\n.finished .breathe {animation:celebrate 2s ease-in-out infinite}\n.sleeping .breathe {animation:sleep 4s ease-in-out infinite}\n.bubble {animation:bubble 2s ease-in-out infinite}\n.bubble.second {animation-delay:.2s}.bubble.third {animation-delay:.4s}\n.spark {transform-box:fill-box;transform-origin:center;animation:twinkle 2s ease-in-out infinite}\n.cursor {animation:cursor 1s steps(1) infinite}\n.working .hand-left {transform-origin:176px 336px;animation:typeL .6s ease-in-out infinite}\n.working .hand-right {transform-origin:336px 336px;animation:typeL .6s ease-in-out .3s infinite}\n@keyframes breathe{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}\n@keyframes blink{0%,43%,49%,100%{transform:scaleY(1)}46%{transform:scaleY(.08)}}\n@keyframes ponder{0%,100%{transform:rotate(-3deg)}50%{transform:rotate(3deg)}}\n@keyframes celebrate{0%,100%{transform:translateY(0)}35%{transform:translateY(-14px)}55%{transform:translateY(0)}}\n@keyframes sleep{0%,100%{transform:scale(1)}50%{transform:scale(1.012,.99)}}\n@keyframes bubble{0%,100%{opacity:.25}50%{opacity:1}}\n@keyframes twinkle{0%,100%{opacity:.4;transform:scale(.8)}50%{opacity:1;transform:scale(1.12)}}\n@keyframes cursor{0%,49%{opacity:1}50%,100%{opacity:0}}\n@keyframes typeL{0%,100%{transform:translateY(0)}50%{transform:translateY(4px)}}\n@media(prefers-reduced-motion:reduce){.breathe,.blink,.head-group,.bubble,.spark,.cursor,.hand-left,.hand-right{animation:none!important}}\n*{animation:none!important;transition:none!important}</style><g id=\"axon\" class=\"idle\"><g class=\"breathe\" transform=\"translate(0 0.000)\"><g id=\"feet\" fill=\"url(#skin)\"><g data-leg=\"left\"><path d=\"M224 366L224 389\" stroke=\"#ED9900\" stroke-width=\"20\" stroke-linecap=\"round\"/><ellipse cx=\"224\" cy=\"390\" rx=\"24\" ry=\"12\"/></g><g data-leg=\"right\"><path d=\"M288 366L288 389\" stroke=\"#ED9900\" stroke-width=\"20\" stroke-linecap=\"round\"/><ellipse cx=\"288\" cy=\"390\" rx=\"24\" ry=\"12\"/></g></g><path d=\"M 215 310 C 193 325 194 362 201 381 C 209 401 303 401 311 381 C 318 362 319 325 297 310 Z\" fill=\"url(#body-fill)\" id=\"body\"/><ellipse id=\"belly\" cx=\"256\" cy=\"356\" rx=\"30\" ry=\"23\" fill=\"#FFE0A0\" opacity=\".48\"/><g class=\"head-group\" transform=\"rotate(0.000 256 282)\"><g id=\"gills-left\"><path d=\"M 143 214 C 114 213 88 188 90 170 C 92 157 105 159 114 170 C 130 190 143 190 150 199 Z\" fill=\"url(#gill-fill)\" /><path d=\"M 139 237 C 110 242 72 232 67 216 C 63 203 75 198 87 206 C 107 217 126 213 143 219 Z\" fill=\"url(#gill-fill)\" /><path d=\"M 144 252 C 129 276 104 289 88 280 C 77 274 84 260 96 257 C 111 253 122 243 140 238 Z\" fill=\"url(#gill-fill)\" /><path d=\"M 113 193 Q 110 178 115 169 M 95 222 Q 82 230 74 226 M 113 266 Q 111 281 100 287\" fill=\"none\" stroke=\"url(#gill-fill)\" stroke-width=\"9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" /></g><g id=\"gills-right\" transform=\"translate(512 0) scale(-1 1)\"><path d=\"M 143 214 C 114 213 88 188 90 170 C 92 157 105 159 114 170 C 130 190 143 190 150 199 Z\" fill=\"url(#gill-fill)\" /><path d=\"M 139 237 C 110 242 72 232 67 216 C 63 203 75 198 87 206 C 107 217 126 213 143 219 Z\" fill=\"url(#gill-fill)\" /><path d=\"M 144 252 C 129 276 104 289 88 280 C 77 274 84 260 96 257 C 111 253 122 243 140 238 Z\" fill=\"url(#gill-fill)\" /><path d=\"M 113 193 Q 110 178 115 169 M 95 222 Q 82 230 74 226 M 113 266 Q 111 281 100 287\" fill=\"none\" stroke=\"url(#gill-fill)\" stroke-width=\"9\" stroke-linecap=\"round\" stroke-linejoin=\"round\" /></g><path d=\"M 256 148 C 174 148 129 168 128 231 C 127 296 161 328 256 328 C 351 328 385 296 384 231 C 383 168 338 148 256 148 Z\" fill=\"url(#skin)\" id=\"head\"/><path d=\"M 256 148 C 174 148 129 168 128 231 C 127 296 161 328 256 328 C 351 328 385 296 384 231 C 383 168 338 148 256 148 Z\" fill=\"url(#gleam)\" id=\"head-light\"/><g id=\"cheeks\" fill=\"#E78120\" opacity=\".28\"><ellipse cx=\"177\" cy=\"261\" rx=\"15\" ry=\"8\"/><ellipse cx=\"335\" cy=\"261\" rx=\"15\" ry=\"8\"/></g><g id=\"eyes\" transform=\"translate(0 0)\" fill=\"#362314\"><g transform=\"translate(205 232)\"><g class=\"blink\"><ellipse cx=\"0\" cy=\"0\" rx=\"8\" ry=\"12.00\"/></g></g><g transform=\"translate(307 232)\"><g class=\"blink\"><ellipse cx=\"0\" cy=\"0\" rx=\"8\" ry=\"12.00\"/></g></g></g><path d=\"M 243 263 Q 256 278 269 263\" fill=\"none\" stroke=\"#362314\" stroke-width=\"5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" id=\"mouth\"/></g><g id=\"hands\"><g class=\"hand-left\" transform=\"translate(0 0.00)\"><ellipse cx=\"164\" cy=\"343\" rx=\"14\" ry=\"19\" transform=\"rotate(-15 164 343)\" fill=\"url(#skin)\"/></g><g class=\"hand-right\" transform=\"translate(0 0.00)\"><ellipse cx=\"348\" cy=\"343\" rx=\"14\" ry=\"19\" transform=\"rotate(15 348 343)\" fill=\"url(#skin)\"/></g></g></g></g></svg>";</script>
